// Prepared only; root owns the dedicated headless run and screenshot review.
export default async function workbenchScenario(review) {
  await review.reducedMotion(true);
  await review.waitFor('window.__modelReview?.ready===true');
  await review.evaluate(`(() => {
    const fixture=window.__modelReview;
    const state={diffs:[],stops:[],sessionSearches:0,fileSearches:0,entries:[{path:'staged.ts',status:'M '},{path:'work.ts',status:' M'},{path:'mixed.ts',status:'MM'},{path:'new.ts',status:'??'}]};
    const mock=(name,fn)=>{window.piDesktop[name]=async(...args)=>{fixture.calls.push({name,args:structuredClone(args)});return fn(...args);};};
    mock('listWorkspaceEntries',path=>path==='src'?[{path:'src/文件.ts',name:'文件.ts',kind:'file',size:140}]:[{path:'src',name:'src',kind:'directory'},{path:'readme.ts',name:'readme.ts',kind:'file',size:120}]);
    mock('readWorkspaceFile',()=> 'const value = "needle";\\n// needle 中文\\nconsole.log(value);\\n');
    mock('getWorkspaceGitStatus',()=>({isRepository:true,branch:'review',entries:state.entries,truncated:false}));
    mock('getWorkspaceGitLog',()=>[]);
    mock('getWorkspaceGitDiff',(path,source)=>{state.diffs.push({path,source});return (source==='staged'?'已暂存 / Staged':'未暂存 / Unstaged')+'\\n--- a/'+path+'\\n+++ b/'+path+'\\n@@ -1,2 +1,2 @@\\n const first = 1;\\n-old needle\\n+new needle '+source+'\\n';});
    mock('startWorkspaceCommand',()=> 'workbench-review-command');
    mock('stopWorkspaceCommand',id=>{state.stops.push(id);fixture.emit('onWorkspaceCommandEvent',{id,type:'exit',code:0});});
    mock('searchSessions',query=>{if(query){state.sessionSearches++;if(state.sessionSearches===1)throw new Error('Review session search failed');}return {sessions:[],truncated:false};});
    mock('searchWorkspaceFiles',()=>{state.fileSearches++;return {files:[{path:'needle.ts',name:'needle.ts',kind:'file'}],truncated:false};});
    state.emit=data=>fixture.emit('onWorkspaceCommandEvent',{id:'workbench-review-command',type:'stdout',data});
    window.__workbenchReview=state;
  })()`);
  await review.viewport(1440,1000);
  await review.click('.pd-workbench-toggle');
  await review.waitFor('document.querySelectorAll(".pd-workbench [data-file-path]").length===2');
  await review.assert('document.querySelector(".pd-workbench").getAttribute("role")==="complementary"','Wide layout remains a nonmodal pane');
  await review.evaluate('document.querySelector(".pd-composer-shell textarea").focus()');
  await review.assert('document.activeElement.matches(".pd-composer-shell textarea")','Parallel mode permits cross-column focus');
  await review.evaluate('window.__workbenchReview.width=Number(document.querySelector(".pd-workbench-resize").getAttribute("aria-valuenow"));document.querySelector(".pd-workbench-resize").focus()');
  await review.key('ArrowLeft');
  await review.assert('Number(document.querySelector(".pd-workbench-resize").getAttribute("aria-valuenow"))===window.__workbenchReview.width+16','Keyboard width adjustment is reflected in layout');
  await review.evaluate('document.querySelector("[data-file-path=src]").focus()');
  await review.settle();
  await review.record('directory-before-enter','({focus:document.activeElement?.outerHTML,calls:window.__modelReview.calls.filter(call=>call.name==="listWorkspaceEntries")})');
  await review.key('Enter');
  await review.record('directory-after-enter','({focus:document.activeElement?.outerHTML,paths:[...document.querySelectorAll(".pd-workbench [data-file-path]")].map(element=>element.getAttribute("data-file-path")),calls:window.__modelReview.calls.filter(call=>call.name==="listWorkspaceEntries")})');
  await review.waitFor(`Boolean(document.querySelector('[data-file-path="src/文件.ts"]'))`);
  await review.key('ArrowLeft');
  await review.waitFor(`Boolean(document.querySelector('[data-file-path="readme.ts"]'))`);
  await review.evaluate('document.querySelector("[data-file-path=src]").focus()');
  await review.key('ArrowDown');
  await review.assert('document.activeElement.getAttribute("data-file-path")==="readme.ts"','Single list entry point supports arrow navigation');
  await review.key('F10',{shift:true});
  await review.waitFor('Boolean(document.querySelector(".pd-workbench-file-menu"))');
  await review.assert('document.querySelector(".pd-workbench-file-menu").getAttribute("aria-label")==="readme.ts" && document.activeElement.getAttribute("role")==="menuitem"','Keyboard file menu binds the selected target');
  await review.key('Escape');
  await review.assert('document.activeElement.getAttribute("data-file-path")==="readme.ts"','Menu Escape restores its file row');
  await review.key('Enter');
  await review.waitFor('Boolean(document.querySelector(".pd-workbench-code-line"))');
  await review.fill('.pd-workbench-reader-tools input','needle');
  await review.assert('document.querySelectorAll(".pd-workbench-reader mark").length===2','File find highlights every occurrence');
  await review.key('Enter');
  await review.assert('document.querySelector("[data-current-match]").closest(".pd-workbench-code-line").textContent.includes("中文")','Enter moves to the next exact occurrence');
  await review.evaluate('document.querySelector(".pd-workbench-preview-resize").focus();window.__workbenchReview.ratio=Number(document.activeElement.getAttribute("aria-valuenow"))');
  await review.key('ArrowUp');
  await review.assert('Number(document.querySelector(".pd-workbench-preview-resize").getAttribute("aria-valuenow"))===window.__workbenchReview.ratio+5','Preview ratio supports keyboard resizing');
  await review.screenshot('workbench-1440-file');
  await review.click('[data-segment-key=git]');
  await review.waitFor(`document.querySelectorAll('[data-git-path="mixed.ts"]').length===2`);
  await review.assert('document.querySelectorAll("[data-git-source=staged]").length===2 && document.querySelectorAll("[data-git-source=unstaged]").length===3','Git XY groups distinguish M-space, space-M, MM and untracked');
  await review.click('[data-git-path="mixed.ts"][data-git-source=staged]');
  await review.waitFor('document.querySelector(".pd-workbench-reader").textContent.includes("new needle staged")');
  await review.click('[data-git-path="mixed.ts"][data-git-source=unstaged]');
  await review.waitFor('document.querySelector(".pd-workbench-reader").textContent.includes("new needle unstaged")');
  await review.assert('window.__workbenchReview.diffs.map(item=>item.source).join(",")==="staged,unstaged"','Selecting a Git group forwards its actual source to IPC');
  await review.assert('document.querySelectorAll(".pd-workbench-code-line.is-added").length===1 && document.querySelectorAll(".pd-workbench-code-line.is-removed").length===1','Unified diff identifies additions and removals');
  await review.viewport(900,1000);
  await review.assert('document.querySelector(".pd-workbench").getAttribute("aria-modal")==="true"','900px layout uses the modal boundary');
  await review.evaluate(`(() => {const pane=document.querySelector('.pd-workbench');window.__workbenchReview.focusables=()=>[...pane.querySelectorAll('button:not(:disabled),input:not(:disabled),[tabindex="0"],summary')].filter(e=>e.getClientRects().length);window.__workbenchReview.focusables().at(-1).focus();})()`);
  await review.key('Tab');
  await review.assert('document.activeElement===window.__workbenchReview.focusables()[0]','Overlay Tab wraps to its first control');
  await review.key('Tab',{shift:true});
  await review.assert('document.activeElement===window.__workbenchReview.focusables().at(-1)','Overlay Shift+Tab wraps to its last control');
  await review.screenshot('workbench-900-git');
  await review.key('Escape');
  await review.assert('!document.querySelector(".pd-workbench").classList.contains("is-open") && document.activeElement.matches(".pd-workbench-toggle")','Escape closes the overlay and restores the trigger');
  await review.viewport(680,1000);
  await review.click('.pd-workbench-toggle');
  await review.click('.pd-workbench-preview-expand');
  await review.assert('document.querySelector(".pd-workbench-body").classList.contains("is-preview-expanded")','Narrow preview expands without discarding list state');
  await review.screenshot('workbench-680-expanded-diff');
  await review.click('.pd-workbench-preview-expand');
  await review.click('[data-segment-key=command]');
  await review.fill('#pd-workbench-command','review command');
  await review.click('.pd-workbench-command-form button[type=submit]');
  await review.waitFor('Boolean(document.querySelector(".pd-workbench-command-result"))');
  await review.evaluate('window.__workbenchReview.emit(Array.from({length:180},(_,i)=>"line "+i+"\\n").join(""))');
  await review.waitFor('document.querySelector(".pd-workbench-reader-body").scrollHeight>document.querySelector(".pd-workbench-reader-body").clientHeight');
  await review.evaluate('document.querySelector(".pd-workbench-reader-body").scrollTop=0;document.querySelector(".pd-workbench-reader-body").dispatchEvent(new Event("scroll"))');
  await review.settle();
  await review.evaluate('window.__workbenchReview.emit("later output\\n".repeat(20))');
  await review.waitFor('document.querySelector(".pd-workbench-reader-body").textContent.includes("later output")');
  await review.assert('document.querySelector(".pd-workbench-reader-body").scrollTop===0','Incoming command output preserves upward reading position');
  await review.clickText('.pd-workbench-reader-tools button','回到底部');
  await review.assert('(()=>{const e=document.querySelector(".pd-workbench-reader-body");return e.scrollHeight-e.scrollTop-e.clientHeight<24;})()','Follow output returns to the bottom');
  await review.evaluate('window.__workbenchReview.emit("omitted".repeat(20000))');
  await review.waitFor('document.querySelector(".pd-workbench-reader-notice")?.textContent.includes("省略")');
  await review.clickText('.pd-workbench-reader-tools button','清空显示');
  await review.assert('window.__workbenchReview.stops.length===0 && document.querySelector(".pd-workbench-command-result-head button")!==null && !document.querySelector(".pd-workbench-reader-body").textContent.includes("omitted")','Clear display keeps the command running and resets retained output');
  await review.click('.pd-workbench-command-result-head button');
  await review.waitFor('!document.querySelector(".pd-workbench-command-result-head button")');
  await review.assert('window.__workbenchReview.stops.length===1','Explicit stop still operates after clearing output');
  await review.key('Escape');
  await review.viewport(1440,1000);
  await review.click('.pd-sidebar-search-trigger');
  await review.fill('.pd-search-input','needle');
  await review.waitFor('document.querySelectorAll(".pd-search-result").length===2');
  await review.key('ArrowDown');
  await review.assert('document.querySelector(".pd-search-result.is-selected").id.includes("retry%3Asessions")','Failed source retry participates in search keyboard navigation');
  await review.key('Enter');
  await review.waitFor('!document.querySelector(".pd-search-result[id*=retry]")');
  await review.assert('window.__workbenchReview.fileSearches===1 && window.__workbenchReview.sessionSearches===2 && document.querySelector(".pd-search-dialog")!==null && document.querySelector(".pd-search-result").textContent.includes("needle.ts")','Only the failed source is retried; successful file and open dialog remain');
  await review.record('workbench-calls','window.__workbenchReview');
  await review.screenshot('workbench-search-retry');
}

if(process.argv.includes('--check')) {
  let count=0;
  const compile=expression=>{new Function(expression);count++;};
  await workbenchScenario({evaluate:async x=>compile(x),waitFor:async x=>compile(x),assert:async x=>compile(x),record:async(_n,x)=>compile(x),click:async()=>{},clickText:async()=>{},settle:async()=>{},screenshot:async()=>{},viewport:async()=>{},fill:async()=>{},key:async()=>{},reducedMotion:async()=>{}});
  console.log(`Prepared ${count} workbench expressions; no browser launched.`);
}
